#include "knn.h"
#include <stdlib.h>
#include <string.h>

const char *const scaling_names[2]={"standard","minmax"};
const char *const metric_names[4]={"squared_euclidean","manhattan","chebyshev","cosine"};
const char *const weighting_names[2]={"uniform","distance"};
static char *read_line(FILE *file){size_t capacity=128,count=0;char *line=malloc(capacity);if(!line)exit(1);int c;while((c=fgetc(file))!=EOF&&c!='\n'){if(count+1==capacity){capacity*=2;char *grown=realloc(line,capacity);if(!grown)exit(1);line=grown;}line[count++]=(char)c;}if(!count&&c==EOF){free(line);return NULL;}line[count]='\0';return line;}
static int fields(char *line,char **parts){int count=0;parts[count++]=line;for(char *p=line;*p;p++)if(*p==','){*p='\0';parts[count++]=p+1;}return count;}
static int read_rows(const char *name,Row *rows,int offset,Dataset *d,bool header_features){char path[128];snprintf(path,sizeof path,"input/%s",name);FILE *file=fopen(path,"r");if(!file)exit(1);char *line=read_line(file),*parts[12];int width=fields(line,parts);if(header_features){d->feature_count=width-3;for(int j=1;j<width-2;j++)strcpy(d->feature_names[j-1],parts[j]);}free(line);int count=0;
 while((line=read_line(file))){int size=fields(line,parts);Row *r=&rows[count];strcpy(r->id,parts[0]);strcpy(r->label,parts[size-2]);for(int j=1;j<size-2;j++)r->values[j-1]=strtod(parts[j],NULL);r->has_target=*parts[size-1]!='\0';if(r->has_target)r->target=strtod(parts[size-1],NULL);r->index=offset+count;r->label_index=-1;count++;free(line);}fclose(file);return count;
}
static void append_integer(Integers *list,int value){if(list->count==list->capacity){list->capacity=list->capacity?list->capacity*2:16;int *grown=realloc(list->values,(size_t)list->capacity*sizeof *grown);if(!grown)exit(1);list->values=grown;}list->values[list->count++]=value;}
static int named_index(const char *word,const char *const *names,int count){for(int j=0;j<count;j++)if(!strcmp(word,names[j]))return j;exit(1);}
static Settings read_settings(void){Settings s={0};FILE *file=fopen("input/params.txt","r");if(!file)exit(1);char *line;while((line=read_line(file))){char *name=strtok(line," "),*word;while((word=strtok(NULL," "))){if(!strcmp(name,"SCALINGS"))s.scalings[s.scaling_count++]=(ScalingMethod)named_index(word,scaling_names,2);else if(!strcmp(name,"K_VALUES"))s.k[s.k_count++]=atoi(word);else if(!strcmp(name,"METRICS"))s.metrics[s.metric_count++]=(Metric)named_index(word,metric_names,4);else if(!strcmp(name,"WEIGHTINGS"))s.weightings[s.weighting_count++]=(Weighting)named_index(word,weighting_names,2);else if(!strcmp(name,"FOLDS"))s.folds=atoi(word);else if(!strcmp(name,"EDIT_K"))s.edit_k=atoi(word);else if(!strcmp(name,"CURVE"))append_integer(&s.curve,atoi(word));else if(!strcmp(name,"BINS"))s.bins[s.bin_count++]=strtod(word,NULL);else if(!strcmp(name,"TOP"))s.top=atoi(word);}free(line);}fclose(file);return s;}
static int compare_names(const void *left,const void *right){return strcmp(left,right);}
void read_dataset(Dataset *d){int train=read_rows("train.csv",d->train,0,d,true),test=read_rows("test.csv",d->test,train,d,false);d->settings=read_settings();for(int j=0;j<train;j++){Row *r=&d->train[j];d->training.values[d->training.count++]=r;bool seen=false;for(int k=0;k<d->label_count;k++)if(!strcmp(r->label,d->labels[k]))seen=true;if(!seen)strcpy(d->labels[d->label_count++],r->label);}if(d->label_count>1)qsort(d->labels,(size_t)d->label_count,sizeof *d->labels,compare_names);for(int j=0;j<test;j++)d->testing.values[d->testing.count++]=&d->test[j];for(int source=0;source<2;source++){Rows *rows=source?&d->testing:&d->training;for(int j=0;j<rows->count;j++)for(int k=0;k<d->label_count;k++)if(!strcmp(rows->values[j]->label,d->labels[k]))rows->values[j]->label_index=k;}}

#ifndef KNN_H
#define KNN_H

#include <stdbool.h>
#include <stdio.h>

#define MAX_ROWS 300
#define MAX_TEST 100
#define MAX_FEATURES 8
#define MAX_CLASSES 300

typedef enum {STANDARD,MINMAX} ScalingMethod;
typedef enum {SQUARED_EUCLIDEAN,MANHATTAN,CHEBYSHEV,COSINE} Metric;
typedef enum {UNIFORM,DISTANCE} Weighting;
typedef struct {int *values,count,capacity;} Integers;
typedef struct {char id[9],label[17];double values[MAX_FEATURES],target;int label_index,index;bool has_target;} Row;
typedef struct {Row *values[MAX_ROWS];int count;} Rows;
typedef struct {int values[MAX_FEATURES],count;} Features;
typedef struct {
 ScalingMethod scalings[2];int scaling_count,k[25],k_count;Metric metrics[4];int metric_count;Weighting weightings[2];int weighting_count;
 int folds,edit_k,top;Integers curve;double bins[99];int bin_count;
} Settings;
typedef struct {
 char feature_names[MAX_FEATURES][17],labels[MAX_CLASSES][17];int feature_count,label_count;
 Row train[MAX_ROWS],test[MAX_TEST];Rows training,testing;Settings settings;
} Dataset;
typedef struct {double centers[MAX_FEATURES],scales[MAX_FEATURES];} Scaling;
typedef struct {int k;Metric metric;Weighting weighting;ScalingMethod scaling;} Model;
typedef struct {Row *row;double distance;} Neighbor;
typedef struct {int label,runner;double share,runner_share,estimate;} Prediction;
typedef struct {Neighbor *values;int queries,references;} Orders;
typedef struct {char **values;int count,capacity;} Lines;
extern const char *const scaling_names[2],*const metric_names[4],*const weighting_names[2];
void read_dataset(Dataset *data);
Scaling compute_scaling(const Rows *rows,ScalingMethod method,int dimension);
void transform(Scaling scaling,const Row *row,Features features,double *vector);
double distance(const double *a,const double *b,int count,Metric metric);
void sort_neighbors(Neighbor *order,int count);
void neighbor_order(const double *query,const Rows *rows,const double *vectors,int width,Metric metric,Neighbor *order);
Prediction predict_order(const Neighbor *order,int count,int k,Weighting weighting);
const char *model_notation(Model model);
void stratified(const Rows *rows,int folds,int *assignment);
Rows training_rows(const Rows *rows,const int *assignment,int excluded_fold);
Orders neighbor_orders(const Rows *training,const Rows *queries,ScalingMethod scaling,Metric metric,Features features,int dimension);
void predict_rows(Model model,const Rows *training,const Rows *queries,Features features,int dimension,Prediction *predictions);
double rmse(const double *errors,int count);
double mae(const double *errors,int count);
double r_squared(const double *errors,const double *targets,int count);
const char *fixed(double value,int places);
const char *real(double value);
double four(double value);
const char *ratio(int numerator,int denominator);
const char *fraction_metric(int numerator,int denominator);
void add_line(Lines *lines,const char *format,...);
void append_lines(Lines *to,const Lines *from);
void append_part(Lines *to,const Lines *part);
void write_report(const char *name,const Lines *lines);

#endif

#include "knn.h"
#include <math.h>
#include <stdlib.h>
#include <string.h>

typedef struct {Model model;Prediction *predictions;int correct;double rmse;} Result;
typedef struct {int classifier,regressor;} Best;
typedef struct {int values[400],count;} Selection;
typedef struct {
 Dataset data;Model models[400];int model_count;Result *results,*loo;Best selected;Features features;int folds[MAX_ROWS],labelled,targets;
 Prediction test_class[MAX_TEST],test_reg[MAX_TEST];Orders test_orders;
} Analysis;
static int minimum(int a,int b){return a<b?a:b;}
static Selection indices(int count){Selection s={0};for(int j=0;j<count;j++)s.values[s.count++]=j;return s;}
static void clear_lines(Lines *lines){for(int j=0;j<lines->count;j++)free(lines->values[j]);free(lines->values);*lines=(Lines){0};}
static void finish_part(Lines *lines,Lines *part){append_part(lines,part);clear_lines(part);}
static Result *initialize_results(const Model *models,int count,int rows){Result *results=calloc((size_t)count,sizeof *results);if(count&&!results)exit(1);for(int j=0;j<count;j++){results[j].model=models[j];results[j].predictions=calloc((size_t)rows,sizeof *results[j].predictions);if(rows&&!results[j].predictions)exit(1);}return results;}
static void finish_results(Result *results,int count,const Rows *rows){for(int j=0;j<count;j++){double errors[MAX_ROWS];for(int i=0;i<rows->count;i++){Prediction p=results[j].predictions[i];results[j].correct+=p.label==rows->values[i]->label_index;errors[i]=p.estimate-rows->values[i]->target;}results[j].rmse=rmse(errors,rows->count);}}
static void free_results(Result *results,int count){for(int j=0;j<count;j++)free(results[j].predictions);free(results);}
static Result *cross_validate(const Model *models,int model_count,const Rows *rows,Features features,int dimension,int folds){
 Result *results=initialize_results(models,model_count,rows->count);int assignment[MAX_ROWS];stratified(rows,folds,assignment);
 for(int f=0;f<folds;f++){Rows training=training_rows(rows,assignment,f),queries={0};int positions[MAX_ROWS];for(int j=0;j<rows->count;j++)if(assignment[j]==f){positions[queries.count]=j;queries.values[queries.count++]=rows->values[j];}Orders cache[8]={0};bool found[8]={0};
  for(int j=0;j<model_count;j++){Model m=models[j];int key=m.scaling*4+m.metric;if(!found[key]){cache[key]=neighbor_orders(&training,&queries,m.scaling,m.metric,features,dimension);found[key]=true;}Orders o=cache[key];for(int k=0;k<queries.count;k++)results[j].predictions[positions[k]]=predict_order(o.values+k*o.references,o.references,m.k,m.weighting);}
  for(int key=0;key<8;key++)free(cache[key].values);
 }
 finish_results(results,model_count,rows);return results;
}
static Result *leave_one_out(const Model *models,int model_count,const Rows *rows,Features features,int dimension){
 Result *results=initialize_results(models,model_count,rows->count);
 for(int i=0;i<rows->count;i++){Rows training={0},queries={.count=1,.values={rows->values[i]}};for(int j=0;j<rows->count;j++)if(j!=i)training.values[training.count++]=rows->values[j];Orders cache[8]={0};bool found[8]={0};
  for(int j=0;j<model_count;j++){Model m=models[j];int key=m.scaling*4+m.metric;if(!found[key]){cache[key]=neighbor_orders(&training,&queries,m.scaling,m.metric,features,dimension);found[key]=true;}results[j].predictions[i]=predict_order(cache[key].values,training.count,m.k,m.weighting);}for(int key=0;key<8;key++)free(cache[key].values);
 }
 finish_results(results,model_count,rows);return results;
}
static Best best(const Result *results,Selection selection){Best b={selection.values[0],selection.values[0]};for(int j=1;j<selection.count;j++){int i=selection.values[j];if(results[i].correct>results[b.classifier].correct)b.classifier=i;if(four(results[i].rmse)<four(results[b.regressor].rmse))b.regressor=i;}return b;}
static int correct(const Rows *rows,const Prediction *predictions){int count=0;for(int j=0;j<rows->count;j++)count+=rows->values[j]->label_index>=0&&rows->values[j]->label_index==predictions[j].label;return count;}
static int errors_for(const Rows *rows,const Prediction *predictions,double *errors,double *targets){int count=0;for(int j=0;j<rows->count;j++)if(rows->values[j]->has_target){errors[count]=predictions[j].estimate-rows->values[j]->target;if(targets)targets[count]=rows->values[j]->target;count++;}return count;}
static int compare_ids(const void *left,const void *right){const Row *a=*(Row *const *)left,*b=*(Row *const *)right;return strcmp(a->id,b->id);}
static Rows sorted_rows(Rows rows){if(rows.count>1)qsort(rows.values,(size_t)rows.count,sizeof *rows.values,compare_ids);return rows;}
static const char *label_counts(const Dataset *d,const Rows *rows){static char buffers[32][8192];static unsigned next;char *text=buffers[next++%32];text[0]='\0';int counts[MAX_CLASSES]={0};for(int j=0;j<rows->count;j++)counts[rows->values[j]->label_index]++;for(int j=0;j<d->label_count;j++)snprintf(text+strlen(text),8192-strlen(text),"%s%s %d",j?" ":"",d->labels[j],counts[j]);return text;}
static Lines evaluation(const Dataset *d,const Rows *rows,const Prediction *predictions){
 int matrix[MAX_CLASSES][MAX_CLASSES]={0};for(int j=0;j<rows->count;j++){int label=rows->values[j]->label_index;if(label>=0)matrix[label][predictions[j].label]++;}Lines lines={0};char text[8192];strcpy(text,"true\\predicted");for(int j=0;j<d->label_count;j++){strcat(text," ");strcat(text,d->labels[j]);}add_line(&lines,"%s",text);
 for(int j=0;j<d->label_count;j++){strcpy(text,d->labels[j]);for(int k=0;k<d->label_count;k++)snprintf(text+strlen(text),sizeof text-strlen(text)," %d",matrix[j][k]);add_line(&lines,"%s",text);}double sums[3]={0};int counts[3]={0};
 for(int j=0;j<d->label_count;j++){int actual=0,predicted=0;for(int k=0;k<d->label_count;k++){actual+=matrix[j][k];predicted+=matrix[k][j];}int tp=matrix[j][j],numerators[3]={tp,tp,2*tp},denominators[3]={predicted,actual,predicted+actual};for(int k=0;k<3;k++)if(denominators[k]){sums[k]+=(double)numerators[k]/denominators[k];counts[k]++;}add_line(&lines,"class %s precision %s recall %s f1 %s support %d",d->labels[j],fraction_metric(tp,predicted),fraction_metric(tp,actual),fraction_metric(2*tp,predicted+actual),actual);}
 const char *averages[3];for(int k=0;k<3;k++)averages[k]=counts[k]?real(sums[k]/counts[k]):"-";add_line(&lines,"macro precision %s recall %s f1 %s",averages[0],averages[1],averages[2]);return lines;
}
static Lines bins(const Dataset *d,const Rows *rows,const Prediction *predictions){const Settings *s=&d->settings;int counts[100]={0},correct_counts[100]={0};double sums[100]={0};for(int j=0;j<rows->count;j++){Row *r=rows->values[j];if(r->label_index<0)continue;Prediction p=predictions[j];int bin=0;while(bin<s->bin_count&&p.share>=s->bins[bin])bin++;counts[bin]++;correct_counts[bin]+=p.label==r->label_index;sums[bin]+=p.share;}Lines lines={0};for(int j=0;j<=s->bin_count;j++){double lower=j?s->bins[j-1]:0;if(!counts[j])add_line(&lines,"bin %s rows 0",fixed(lower,2));else add_line(&lines,"bin %s rows %d correct %s share %s",fixed(lower,2),counts[j],ratio(correct_counts[j],counts[j]),real(sums[j]/counts[j]));}return lines;}
static Features without_feature(Features features,int position){Features out={0};for(int j=0;j<features.count;j++)if(j!=position)out.values[out.count++]=features.values[j];return out;}
static const char *feature_names(const Dataset *d,Features features){static char buffers[8][256];static unsigned next;char *text=buffers[next++%8];text[0]='\0';for(int j=0;j<features.count;j++){if(j)strcat(text," ");strcat(text,d->feature_names[features.values[j]]);}return text;}
static Lines feature_lines(const Analysis *a){const Dataset *d=&a->data;Model m=a->models[a->selected.classifier];Features features=a->features,selected=features;int best_count=a->results[a->selected.classifier].correct,n=d->training.count;Lines lines={0};add_line(&lines,"feature_selection %s",model_notation(m));add_line(&lines,"start features %s correct %s",feature_names(d,features),ratio(best_count,n));int step=0;
 while(features.count>=3){int counts[MAX_FEATURES],choice=0;for(int j=0;j<features.count;j++){Result *result=cross_validate(&m,1,&d->training,without_feature(features,j),d->feature_count,d->settings.folds);counts[j]=result[0].correct;free_results(result,1);if(counts[j]>counts[choice])choice=j;}char candidates[512]="";for(int j=0;j<features.count;j++)snprintf(candidates+strlen(candidates),sizeof candidates-strlen(candidates),"%s%s %d",j?" ":"",d->feature_names[features.values[j]],counts[j]);int removed=features.values[choice];features=without_feature(features,choice);add_line(&lines,"step %d remove %s correct %s candidates %s",++step,d->feature_names[removed],ratio(counts[choice],n),candidates);if(counts[choice]>=best_count){best_count=counts[choice];selected=features;}}
 Prediction test[MAX_TEST];predict_rows(m,&d->training,&d->testing,selected,d->feature_count,test);add_line(&lines,"selected features %s correct %s",feature_names(d,selected),ratio(best_count,n));add_line(&lines,"selected test %s",ratio(correct(&d->testing,test),a->labelled));return lines;
}
static Lines nested_lines(const Analysis *a){const Dataset *d=&a->data;Lines lines={0};add_line(&lines,"nested_cross_validation folds %d",d->settings.folds);double nested_errors[MAX_ROWS];int total_correct=0;
 for(int f=0;f<d->settings.folds;f++){Rows training=training_rows(&d->training,a->folds,f),queries={0};int positions[MAX_ROWS];for(int j=0;j<d->training.count;j++)if(a->folds[j]==f){positions[queries.count]=j;queries.values[queries.count++]=d->training.values[j];}Result *inner=cross_validate(a->models,a->model_count,&training,a->features,d->feature_count,d->settings.folds);Best selected=best(inner,indices(a->model_count));Prediction cp[MAX_ROWS],rp[MAX_ROWS];predict_rows(a->models[selected.classifier],&training,&queries,a->features,d->feature_count,cp);predict_rows(a->models[selected.regressor],&training,&queries,a->features,d->feature_count,rp);int count=correct(&queries,cp);total_correct+=count;double errors[MAX_ROWS];errors_for(&queries,rp,errors,NULL);for(int j=0;j<queries.count;j++)nested_errors[positions[j]]=errors[j];add_line(&lines,"fold %d classifier %s inner %s outer %s",f+1,model_notation(a->models[selected.classifier]),real((double)inner[selected.classifier].correct/training.count),ratio(count,queries.count));add_line(&lines,"fold %d regressor %s inner %s outer %s",f+1,model_notation(a->models[selected.regressor]),real(inner[selected.regressor].rmse),real(rmse(errors,queries.count)));free_results(inner,a->model_count);}
 add_line(&lines,"nested accuracy %s rmse %s",ratio(total_correct,d->training.count),real(rmse(nested_errors,d->training.count)));return lines;
}
static bool model_matches(Model m,int kind,int value){if(kind==0)return m.k==value;if(kind==1)return m.metric==(Metric)value;if(kind==2)return m.weighting==(Weighting)value;return m.scaling==(ScalingMethod)value;}
static Lines best_per(const Analysis *a,int kind){const Settings *s=&a->data.settings;const char *kinds[4]={"k","metric","weighting","scaling"};int count=kind==0?s->k_count:kind==1?s->metric_count:kind==2?s->weighting_count:s->scaling_count;Lines lines={0};add_line(&lines,"best per %s",kinds[kind]);for(int j=0;j<count;j++){int value=kind==0?s->k[j]:kind==1?(int)s->metrics[j]:kind==2?(int)s->weightings[j]:(int)s->scalings[j];Selection selection={0};for(int k=0;k<a->model_count;k++)if(model_matches(a->models[k],kind,value))selection.values[selection.count++]=k;Best selected=best(a->results,selection);Result c=a->results[selected.classifier],r=a->results[selected.regressor];char number[32];snprintf(number,sizeof number,"%d",value);const char *text=kind==0?number:kind==1?metric_names[value]:kind==2?weighting_names[value]:scaling_names[value];add_line(&lines,"%s=%s classifier %s accuracy %s regressor %s rmse %s",kinds[kind],text,model_notation(c.model),real((double)c.correct/a->data.training.count),model_notation(r.model),real(r.rmse));}return lines;}
static Selection rank_models(const Analysis *a,bool regression){Selection order=indices(a->model_count);for(int j=1;j<order.count;j++){int value=order.values[j],k=j;while(k>0){int previous=order.values[k-1];bool before=regression?(four(a->results[value].rmse)<four(a->results[previous].rmse)||(four(a->results[value].rmse)==four(a->results[previous].rmse)&&value<previous)):(a->results[value].correct>a->results[previous].correct||(a->results[value].correct==a->results[previous].correct&&value<previous));if(!before)break;order.values[k]=previous;k--;}order.values[k]=value;}return order;}
static Lines metrics_lines(const Analysis *a){
 const Dataset *d=&a->data;const Settings *s=&d->settings;int n=d->training.count;Result c=a->results[a->selected.classifier],r=a->results[a->selected.regressor];Lines lines={0},part={0};
 add_line(&lines,"data train %d test %d labelled %d targets %d features %d classes %d",n,d->testing.count,a->labelled,a->targets,d->feature_count,d->label_count);add_line(&lines,"classes %s",label_counts(d,&d->training));
 for(int j=0;j<s->scaling_count;j++){ScalingMethod method=s->scalings[j];Scaling scale=compute_scaling(&d->training,method,d->feature_count);add_line(&part,"scaling %s",scaling_names[method]);for(int k=0;k<d->feature_count;k++)add_line(&part,"%s center %s scale %s",d->feature_names[k],fixed(scale.centers[k],6),fixed(scale.scales[k],6));finish_part(&lines,&part);}
 add_line(&part,"folds %d",s->folds);for(int f=0;f<s->folds;f++){Rows rows={0};for(int j=0;j<n;j++)if(a->folds[j]==f)rows.values[rows.count++]=d->training.values[j];add_line(&part,"fold %d size %d %s",f+1,rows.count,label_counts(d,&rows));}finish_part(&lines,&part);
 add_line(&part,"grid %d",a->model_count);add_line(&part,"best_classifier %s correct %s rmse %s",model_notation(c.model),ratio(c.correct,n),real(c.rmse));add_line(&part,"best_regressor %s rmse %s correct %s",model_notation(r.model),real(r.rmse),ratio(r.correct,n));finish_part(&lines,&part);
 Selection accuracy=rank_models(a,false),regression=rank_models(a,true);add_line(&part,"top %d by accuracy",s->top);for(int j=0;j<minimum(s->top,accuracy.count);j++){Result value=a->results[accuracy.values[j]];add_line(&part,"%d %s correct %s rmse %s",j+1,model_notation(value.model),ratio(value.correct,n),real(value.rmse));}finish_part(&lines,&part);
 add_line(&part,"top %d by rmse",s->top);for(int j=0;j<minimum(s->top,regression.count);j++){Result value=a->results[regression.values[j]];add_line(&part,"%d %s rmse %s correct %s",j+1,model_notation(value.model),real(value.rmse),ratio(value.correct,n));}finish_part(&lines,&part);for(int kind=0;kind<4;kind++){part=best_per(a,kind);finish_part(&lines,&part);}
 add_line(&part,"classifier folds");for(int f=0;f<s->folds;f++){int count=0,size=0;for(int j=0;j<n;j++)if(a->folds[j]==f){size++;count+=c.predictions[j].label==d->train[j].label_index;}add_line(&part,"fold %d correct %s",f+1,ratio(count,size));}finish_part(&lines,&part);
